}
function drawSparklines() {
  document.querySelectorAll('canvas.spark').forEach(canvas => {
    const trend = canvas.dataset.trend || 'up';
    const ctx = canvas.getContext('2d');
    const w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);
    const pts = [];
    let y = h/2;
    for(let i=0;i<12;i++){
      if(trend==='up') y += (Math.random()-0.35)*5;
      else if(trend==='down') y += (Math.random()-0.65)*5;
      else y += (Math.random()-0.5)*3;
      pts.push(Math.max(3, Math.min(h-3, y)));
    }
    const color = trend==='down' ? '#ef5350' : trend==='flat' ? '#9090a8' : '#26a69a';
    ctx.beginPath();
    pts.forEach((p,i) => i===0 ? ctx.moveTo(i*(w/11),p) : ctx.lineTo(i*(w/11),p));
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    const grad = ctx.createLinearGradient(0,0,0,h);
    grad.addColorStop(0, color.replace(')',', 0.2)').replace('rgb','rgba'));
    grad.addColorStop(1, color.replace(')',', 0)').replace('rgb','rgba'));
    ctx.lineTo(w, h); ctx.lineTo(0, h); ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();
  });
}
