  const minP = Math.min(...prices)*0.998;
  const maxP = Math.max(...prices)*1.002;
  const priceRange = maxP - minP;

  const xScale = i => padL + (i / (chartData.length-1)) * chartW;
  const yScale = p => padT + chartH - ((p-minP)/priceRange)*chartH;

  // Grid
  ctx.strokeStyle = '#1e1e2a';
  ctx.lineWidth = 1;
  for(let i=0;i<=5;i++) {
    const y = padT + (chartH/5)*i;
    ctx.beginPath(); ctx.moveTo(padL,y); ctx.lineTo(w-padR,y); ctx.stroke();
    const priceLabel = (maxP - (priceRange/5)*i).toFixed(2);
    ctx.fillStyle = '#5a5a72'; ctx.font = '10px JetBrains Mono,monospace';
    ctx.textAlign = 'right';
    ctx.fillText(priceLabel, padL-4, y+4);
  }

  if(currentChartType === 'line' || currentChartType === 'area') {
    ctx.beginPath();
    chartData.forEach((d,i) => {
