    chartData.forEach((d,i) => {
      const x = xScale(i);
      const isUp = d.close >= d.open;
      const color = isUp ? '#26a69a' : '#ef5350';
      ctx.strokeStyle = color; ctx.fillStyle = color;
      // Wick
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, yScale(d.high));
      ctx.lineTo(x, yScale(d.low));
      ctx.stroke();
      // Body
      const bodyTop = yScale(Math.max(d.open,d.close));
      const bodyBot = yScale(Math.min(d.open,d.close));
      const bodyH = Math.max(1, bodyBot-bodyTop);
      ctx.fillRect(x-candleW/2, bodyTop, candleW, bodyH);
    });
  }

  // Volume bars
  const volMax = Math.max(...chartData.map(d=>d.vol));
  const volH = 40;
  chartData.forEach((d,i) => {
    const x = xScale(i);
    const barH = (d.vol/volMax)*volH;
    const isUp = d.close >= d.open;
    ctx.fillStyle = isUp ? 'rgba(38,166,154,0.3)' : 'rgba(239,83,80,0.3)';
    const bw = Math.max(1, chartW/chartData.length*0.7);
    ctx.fillRect(x-bw/2, padT+chartH-barH, bw, barH);
  });

  // Current price line
  const lastPrice = chartData[chartData.length-1].close;
  const lineY = yScale(lastPrice);
  ctx.setLineDash([4,4]);
  ctx.strokeStyle = '#ef5350'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(padL,lineY); ctx.lineTo(w-padR,lineY); ctx.stroke();
  ctx.setLineDash([]);
  // Price label
  ctx.fillStyle = '#ef5350';
  ctx.fillRect(w-padR, lineY-10, padR+60, 20);
  ctx.fillStyle = '#fff'; ctx.textAlign='left'; ctx.font='bold 10px JetBrains Mono,monospace';
