  --border:#2a2a3a;--text:#e8e8f0;--text2:#9090a8;--text3:#5a5a72;
  --green:#26a69a;--red:#ef5350;--blue:#2962ff;--teal:#00bcd4;--gold:#ffd700;
  --font:'Inter',sans-serif;--mono:'JetBrains Mono',monospace;
}
body{background:var(--bg);color:var(--text);font-family:var(--font);font-size:14px;line-height:1.5;min-height:100vh}
nav{background:rgba(15,15,20,0.95);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100;backdrop-filter:blur(12px)}
.nav-inner{max-width:1440px;margin:0 auto;display:flex;align-items:center;height:52px;padding:0 20px}
.logo{display:flex;align-items:center;gap:8px;text-decoration:none;margin-right:32px}
.logo-icon{width:28px;height:28px;background:var(--blue);border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:800;color:#fff}
.logo-text{font-size:17px;font-weight:700;color:var(--text);letter-spacing:-0.3px}
.logo-text span{color:var(--blue)}
.nav-links{display:flex;gap:4px;flex:1}
.nav-link{color:var(--text2);text-decoration:none;font-size:13px;font-weight:500;padding:6px 12px;border-radius:6px;transition:all 0.15s}
.nav-link:hover,.nav-link.active{color:var(--text);background:var(--bg3)}
.nav-actions{display:flex;gap:8px;align-items:center}
.btn{padding:7px 16px;border-radius:6px;font-size:13px;font-weight:600;cursor:pointer;transition:all 0.15s;border:none;text-decoration:none}
.btn-ghost{background:transparent;color:var(--text2);border:1px solid var(--border)}
.btn-ghost:hover{color:var(--text)}
.btn-primary{background:var(--blue);color:#fff}
.btn-primary:hover{background:#3d75ff}

/* ASSET TABS */
.asset-tabs{background:var(--bg2);border-bottom:1px solid var(--border);overflow-x:auto;scrollbar-width:none;position:sticky;top:52px;z-index:50}
.asset-tabs::-webkit-scrollbar{display:none}
.asset-tabs-inner{max-width:1440px;margin:0 auto;display:flex;padding:0 20px}
.asset-tab{padding:14px 20px;font-size:13px;font-weight:600;color:var(--text2);cursor:pointer;border-bottom:2px solid transparent;transition:all 0.2s;white-space:nowrap;text-decoration:none;display:block}
.asset-tab:hover{color:var(--text)}
.asset-tab.active{color:var(--blue);border-bottom-color:var(--blue)}

/* CONTENT */
.main-content{max-width:1440px;margin:0 auto;padding:0 20px 40px}
.market-section{padding-top:32px;border-top:1px solid var(--border);margin-top:32px}
.market-section:first-child{border-top:none;margin-top:0;padding-top:32px}
.section-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}
.section-title{font-size:20px;font-weight:700;color:var(--text)}
.section-link{font-size:12px;color:var(--blue);text-decoration:none;font-weight:500}

/* CHART TYPE BAR */
.chart-type-bar{display:flex;gap:4px;align-items:center;flex-wrap:wrap}
.ct-btn{background:transparent;border:1px solid var(--border);color:var(--text2);font-size:11px;font-weight:600;padding:4px 9px;border-radius:4px;cursor:pointer;font-family:var(--mono);transition:all 0.15s}
.ct-btn:hover{color:var(--text);border-color:var(--text3)}
.ct-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
.ct-divider{height:16px;width:1px;background:var(--border);margin:0 2px}

/* TABLES */
.market-table{width:100%;border-collapse:collapse;background:var(--bg2);border:1px solid var(--border);border-radius:10px;overflow:hidden}
.market-table th{background:var(--bg3);padding:10px 14px;text-align:left;font-size:11px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:0.5px;border-bottom:1px solid var(--border)}
.market-table td{padding:11px 14px;border-bottom:1px solid rgba(42,42,58,0.4);font-size:13px;vertical-align:middle}
.market-table tr:last-child td{border-bottom:none}
.market-table tr:hover td{background:rgba(30,30,42,0.6)}
.sym{font-family:var(--mono);font-weight:700;font-size:12px;color:var(--blue)}
.price-val{font-family:var(--mono);font-weight:500}
.up{color:var(--green);font-weight:600;font-family:var(--mono);font-size:12px}
.down{color:var(--red);font-weight:600;font-family:var(--mono);font-size:12px}
.flat{color:var(--text3);font-weight:600;font-family:var(--mono);font-size:12px}

/* MINI SPARK */
canvas.mspark{display:inline-block;vertical-align:middle}

/* GRID LAYOUTS */
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:20px}
@media(max-width:900px){.two-col{grid-template-columns:1fr}}
.three-col{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px}
@media(max-width:1000px){.three-col{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.three-col{grid-template-columns:1fr}}

/* MOVER CARDS */
.mover-card{background:var(--bg2);border:1px solid var(--border);border-radius:10px;overflow:hidden}
.mover-card-header{background:var(--bg3);padding:12px 16px;display:flex;align-items:center;justify-content:space-between}
.mover-card-title{font-size:13px;font-weight:700;color:var(--text)}
.session-tabs{display:flex;gap:2px}
.session-tab{padding:4px 9px;border-radius:4px;font-size:11px;font-weight:600;cursor:pointer;color:var(--text2);background:transparent;border:none;transition:all 0.15s}
.session-tab.active{background:var(--bg4);color:var(--text)}
.mover-item{display:flex;align-items:center;justify-content:space-between;padding:10px 16px;border-bottom:1px solid rgba(42,42,58,0.4)}
.mover-item:last-child{border-bottom:none}
.mover-rank{width:20px;font-size:11px;color:var(--text3);font-weight:700}
.mover-info{flex:1}
.mover-name{font-size:12px;font-weight:600;color:var(--text)}
.mover-ticker{font-size:11px;color:var(--text3);font-family:var(--mono)}
.mover-pct{font-size:13px;font-weight:700;font-family:var(--mono)}

/* BOND TABLE */
.bond-table{width:100%;border-collapse:collapse;background:var(--bg2);border:1px solid var(--border);border-radius:10px;overflow:hidden}
.bond-table th{background:var(--bg3);padding:10px 14px;text-align:left;font-size:11px;font-weight:600;color:var(--text3);text-transform:uppercase;border-bottom:1px solid var(--border)}
.bond-table td{padding:11px 14px;border-bottom:1px solid rgba(42,42,58,0.4);font-size:13px}
.bond-table tr:last-child td{border-bottom:none}
.bond-table tr:hover td{background:rgba(30,30,42,0.6)}
.yield-bar{display:inline-block;height:4px;background:var(--blue);border-radius:2px;vertical-align:middle;margin-left:8px;transition:width 0.3s}

/* EARNINGS TABLE */
.earn-table{width:100%;border-collapse:collapse;background:var(--bg2);border:1px solid var(--border);border-radius:10px;overflow:hidden}
.earn-table th{background:var(--bg3);padding:10px 14px;text-align:left;font-size:11px;font-weight:600;color:var(--text3);text-transform:uppercase;border-bottom:1px solid var(--border)}
.earn-table td{padding:10px 14px;border-bottom:1px solid rgba(42,42,58,0.4);font-size:12px}
.earn-table tr:last-child td{border-bottom:none}
.earn-table tr:hover td{background:rgba(30,30,42,0.6)}
.beat-badge{display:inline-block;background:rgba(38,166,154,0.15);color:var(--green);padding:2px 6px;border-radius:3px;font-size:10px;font-weight:700}
.miss-badge{display:inline-block;background:rgba(239,83,80,0.15);color:var(--red);padding:2px 6px;border-radius:3px;font-size:10px;font-weight:700}
.pending-badge{display:inline-block;background:rgba(255,152,0,0.12);color:#ff9800;padding:2px 6px;border-radius:3px;font-size:10px;font-weight:700}

/* CRYPTO CARDS */
.crypto-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-bottom:20px}
.crypto-card{background:var(--bg2);border:1px solid var(--border);border-radius:8px;padding:14px;cursor:pointer;transition:all 0.2s}
.crypto-card:hover{border-color:rgba(41,98,255,0.4);transform:translateY(-1px)}
.crypto-name{font-size:12px;color:var(--text2);margin-bottom:2px}
.crypto-price{font-size:18px;font-weight:700;font-family:var(--mono);color:var(--text)}
.crypto-chg{font-size:12px;font-weight:600;margin-top:2px}
</style>
</head>
