function drawSpark(canvas) {
  const trend = canvas.dataset.trend || 'up';
  const ctx = canvas.getContext('2d');
  const w = canvas.width, h = canvas.height;
  ctx.clearRect(0,0,w,h);
  const pts = [];
  let y = h/2;
  for(let i=0;i<12;i++){
    if(trend==='up') y += (Math.random()-0.38)*4;
    else if(trend==='down') y += (Math.random()-0.62)*4;
    else y += (Math.random()-0.5)*2.5;
    pts.push(Math.max(3,Math.min(h-3,y)));
  }
  const color = trend==='down' ? '#ef5350' : trend==='flat' ? '#9090a8' : '#26a69a';
  ctx.beginPath();
  pts.forEach((p,i) => i===0 ? ctx.moveTo(i*(w/11),p) : ctx.lineTo(i*(w/11),p));
  ctx.strokeStyle=color; ctx.lineWidth=1.5; ctx.stroke();
}
