<script>
function filterCategory(cat, chip) {
  document.querySelectorAll('.hero-chip').forEach(c => c.classList.remove('active'));
  chip.classList.add('active');
  const cards = document.querySelectorAll('.broker-card');
  cards.forEach(card => {
    const cardCat = card.dataset.cat || '';
    card.style.display = (cat === 'all' || cardCat.includes(cat)) ? 'block' : 'none';
  });
  const visible = [...cards].filter(c => c.style.display !== 'none').length;
  document.querySelector('.filter-count').textContent = `Showing ${visible} of 247 brokers`;
}
function setRatingTab(btn, mode) {
  btn.closest('.tab-bar').querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  const cards = [...document.querySelectorAll('.broker-card')];
  if(mode === 'best') {
    cards.sort((a,b) => {
      const ra = parseFloat(a.querySelector('.rating-val').textContent);
      const rb = parseFloat(b.querySelector('.rating-val').textContent);
      return rb - ra;
    });
    cards.forEach(c => document.getElementById('brokerList').appendChild(c));
  }
}
